"""Produce reviewed repository-local Dependabot automation callers from the OSS registry."""

from __future__ import annotations

import argparse
import json
import re
from pathlib import Path

HERE = Path(__file__).resolve().parent


def render(package, shared_ref, minute):
    if not re.fullmatch("[a-f0-9]{40}", shared_ref):
        raise ValueError("Use an immutable shared-action commit SHA")
    if not 0 <= minute <= 59:
        raise ValueError("Invalid hourly minute")
    return (
        """# Generated by ArturSepp/scripts/generate_dependabot_automation.py.
# Shared policy updates require review; do not replace the immutable action SHA with a branch.
name: Dependabot merge monitor
on:
  workflow_run:
    workflows: ["Required checks"]
    types: [completed]
  schedule:
    - cron: "MINUTE * * * *"
  workflow_dispatch:
    inputs:
      dry_run:
        description: Report decisions without merges or notification writes
        type: boolean
        default: false
permissions: {}
concurrency:
  group: dependabot-merge-${{ github.repository }}
  cancel-in-progress: false
env:
  FORCE_JAVASCRIPT_ACTIONS_TO_NODE24: true
jobs:
  merge:
    if: >-
      github.repository == 'ArturSepp/REPO' &&
      github.ref == 'refs/heads/main' &&
      (github.event_name != 'workflow_run' || github.event.workflow_run.event == 'pull_request')
    runs-on: ubuntu-latest
    timeout-minutes: 15
    permissions:
      contents: write
      pull-requests: write
      issues: write
      actions: read
      checks: read
      statuses: read
    steps:
      - uses: ArturSepp/ArturSepp/.github/actions/dependabot-merge@SHARED_REF
        with:
          github-token: ${{ github.token }}
          apply: ${{ github.event_name != 'workflow_dispatch' || !inputs.dry_run }}
""".replace("MINUTE", str(minute))
        .replace("REPO", package["repo"])
        .replace("SHARED_REF", shared_ref)
    )


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--shared-ref", required=True)
    parser.add_argument("--package", action="append", default=[])
    parser.add_argument("--output-dir", type=Path, required=True)
    args = parser.parse_args(argv)
    registry = json.loads((HERE / "public_registry.json").read_text(encoding="utf-8"))
    if args.package and set(args.package) - {p["repo"] for p in registry["packages"]}:
        parser.error("Unknown registered package")
    for index, package in enumerate(registry["packages"]):
        if args.package and package["repo"] not in args.package:
            continue
        target = (
            args.output_dir
            / package["local_dir"]
            / ".github/workflows/dependabot-merge.yml"
        )
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(
            render(package, args.shared_ref, 7 + index * 4),
            encoding="utf-8",
            newline="\n",
        )
        print(str(target))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
